
.protagonist-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 10px 14px;
  background: var(--c-bg-base);
  border-bottom: 1px solid var(--c-border);
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  position: relative;
  overflow: hidden;
}

.stat-icon {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.cash-card .stat-icon {
  background: var(--c-cash-soft);
  color: var(--c-cash);
  border: 1px solid rgba(46, 229, 157, 0.35);
}

.hehuan-card .stat-icon {
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
  border: 1px solid var(--c-border-gold);
}

.stamina-card .stat-icon {
  background: var(--c-primary-soft);
  color: var(--c-primary);
  border: 1px solid var(--c-border-highlight);
}

.stat-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.stat-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.stat-label {
  font-size: 0.72rem;
  color: var(--c-text-muted);
  font-weight: 600;
}

.stat-tier {
  font-size: 0.66rem;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--c-text-secondary);
}

.stat-value {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.15;
}

.cash-val {
  color: var(--c-cash);
  text-shadow: 0 0 8px rgba(46, 229, 157, 0.25);
}

.hehuan-val {
  color: var(--c-accent-gold);
  text-shadow: 0 0 8px rgba(245, 185, 66, 0.25);
}

.unit {
  font-size: 0.72rem;
  font-weight: 600;
  opacity: 0.85;
}

.stamina-num {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
}

.stamina-num.stamina-high {
  color: var(--c-stamina);
}

.stamina-num.stamina-mid {
  color: var(--c-accent-gold);
}

.stamina-num.stamina-low {
  color: var(--c-danger);
}

.stamina-track {
  width: 100%;
  height: 7px;
  background: rgba(13, 8, 20, 0.8);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  overflow: hidden;
  margin-top: 2px;
}

.stamina-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.3s ease;
}

.stamina-fill.stamina-high {
  background: linear-gradient(90deg, #2563eb, var(--c-stamina));
}

.stamina-fill.stamina-mid {
  background: linear-gradient(90deg, #d97706, var(--c-accent-gold));
}

.stamina-fill.stamina-low {
  background: linear-gradient(90deg, #991b1b, var(--c-danger));
}

@media (max-width: 640px) {
  .protagonist-stats {
    grid-template-columns: 1fr;
  }
}
