
.arsenal-panel {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.arsenal-column {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.col-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--c-accent-gold);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--c-border);
}

.entry-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.entry-card {
  background: rgba(13, 8, 20, 0.55);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 7px 9px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.skill-card {
  border-left: 2.5px solid var(--c-accent-gold);
}

.item-card {
  border-left: 2.5px solid var(--c-primary);
}

.entry-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.entry-name {
  font-size: 0.82rem;
  font-weight: 800;
  color: #fff;
}

.entry-tag {
  font-size: 0.66rem;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
}

.count-pill {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--c-primary-soft);
  color: var(--c-primary);
}

.entry-desc {
  font-size: 0.74rem;
  line-height: 1.4;
  color: var(--c-text-secondary);
}

.empty-col {
  padding: 14px 8px;
  text-align: center;
  font-size: 0.75rem;
  color: var(--c-text-muted);
  font-style: italic;
}

@media (max-width: 640px) {
  .arsenal-panel {
    grid-template-columns: 1fr;
  }
}
